python3 -c "
# Simulate the timezone parsing logic
def parse_tz(tz):
    sign = tz[0]
    if ':' in tz:
        tzh, tzm = tz[1:].split(':')
    elif len(tz) == 4:  # 'snnn'
        tzh, tzm = tz[1], tz[2:4]
    else:
        tzh, tzm = tz[1:3], tz[3:5]
    offset = int(tzm) + int(tzh) * 60
    if sign == '-':
        offset = -offset
    return offset

tests = [
    '+05:30', '+0530', '-05:30', '-0530', '+00:00', 
    '+5:30', '+530', '-5:30', '-530', '+05', '+5',
    '+0', '+00', '+000', '+0000',
]
for tz in tests:
    try:
        offset = parse_tz(tz)
        print(f'{tz!r:10} -> {offset} minutes ({offset/60:+.1f} hours)')
    except Exception as e:
        print(f'{tz!r:10} -> ERROR: {e}')
"
